  border-radius: 16px;
  color: var(--text);
  outline: none;
  padding: 14px;
  width: 100%;
}

textarea {
  min-height: 140px;
  resize: vertical;
}

.result-header,
.action-row {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: space-between;
}

