  min-height: 180px;
}

.device-shell {
  background: linear-gradient(180deg, #132d3b, #07131c);
  border-radius: 36px;
  display: grid;
  gap: 18px;
  padding: 26px;
}

.device-top,
.scan-card,
.inline-warning {
  background: rgba(255, 255, 255, 0.07);
  border-radius: 18px;
  padding: 14px;
}

.inline-warning {
  border: 1px solid rgba(246, 184, 75, 0.35);
  color: var(--amber);
}

.big-input {
  align-items: center;
  display: flex;
  gap: 10px;
}

.big-input input {
  font-size: 42px;
  font-weight: 900;
}

.device-actions {
  display: grid;
  gap: 12px;
  grid-template-columns: 1fr 1fr;
}

.feedback-form {
  display: grid;
  gap: 14px;
  grid-template-columns: 1fr auto;
}

.mini-row,
.leader-row,
.cost-row {
  margin-bottom: 12px;
}

.mini-row,
.leader-row {
  align-items: flex-start;
  flex-direction: column;
}

.state-card {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 20px;
  padding: 24px;
}

.state-card.error {
  color: var(--red);
}

.check-line {
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--line);
  border-radius: 14px;
  margin: 8px 0;
  padding: 10px 12px;
}

.check-line::before {
  color: var(--cyan);
  content: "鉁?";
  font-weight: 900;
}

.trend-chart {
  align-items: end;
  display: grid;
  gap: 14px;
  grid-template-columns: repeat(7, 1fr);
  min-height: 220px;
}

.trend-chart div {
  align-items: center;
  display: flex;
  flex-direction: column;
  gap: 10px;
  justify-content: end;
}

.trend-chart i {
  background: linear-gradient(180deg, var(--cyan), var(--blue));
  border-radius: 999px 999px 8px 8px;
  display: block;
  min-height: 28px;
  width: 42px;
}

.timeline {
  display: grid;
  gap: 14px;
  margin-top: 18px;
}

.timeline div {
  align-items: flex-start;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--line);
  border-radius: 18px;
  display: grid;
  gap: 14px;
  grid-template-columns: 42px 1fr;
  padding: 14px;
}

.timeline span {
  align-items: center;
  background: rgba(55, 215, 196, 0.15);
  border-radius: 14px;
  color: var(--cyan);
  display: flex;
  font-weight: 900;
  height: 42px;
  justify-content: center;
}

.timeline p {
  margin: 0;
}

.workflow-chain {
  display: grid;
  gap: 12px;
}

.workflow-chain div {
  align-items: center;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--line);
  border-radius: 18px;
  display: grid;
  gap: 10px;
  grid-template-columns: 1fr 120px auto;
  padding: 14px;
}

.workflow-chain span {
  color: var(--muted);
}

.loop-grid {
  display: grid;
  gap: 12px;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
}

.loop-grid article {
  background: linear-gradient(180deg, rgba(55, 215, 196, 0.1), rgba(255, 255, 255, 0.035));
  border: 1px solid var(--line);
  border-radius: 18px;
  display: grid;
  gap: 10px;
  padding: 16px;
  position: relative;
}

.loop-grid article:not(:last-child)::after {
  color: var(--cyan);
  content: "鈫?;
  font-size: 22px;
  position: absolute;
  right: -16px;
  top: 42%;
}

.hero.compact {
